import { useNavigate } from "react-router-dom";

export default function Navbar() {

  const nav = useNavigate();

  const logout = () => {

    localStorage.removeItem("token");

    nav("/");
  };

  return (

    <div className="navbar">

      <h2>HRMS Dashboard</h2>

      <button
        className="logout-btn"
        onClick={logout}
      >
        Logout
      </button>

    </div>
  );
}
